/* Generated by Trae Work */
(function() {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim();
  var accent2 = style.getPropertyValue('--accent2').trim();
  var ink = style.getPropertyValue('--ink').trim();
  var muted = style.getPropertyValue('--muted').trim();
  var rule = style.getPropertyValue('--rule').trim();
  var bg2 = style.getPropertyValue('--bg2').trim();
  var ok = style.getPropertyValue('--ok').trim();
  var warn = style.getPropertyValue('--warn').trim();
  var bad = style.getPropertyValue('--bad').trim();

  fetch('assets/report-data.json')
    .then(function(r) { return r.json(); })
    .then(function(data) { renderAll(data); })
    .catch(function(err) {
      document.body.innerHTML += '<p style="padding:2rem;color:' + bad + '">无法加载 report-data.json：' + err.message + '</p>';
    });

  function renderAll(data) {
    renderFuncBars(data.func_coverage);
    renderCategoryPie(data.category_counts);
    renderFileStack(data.file_summary);
  }

  // ── Chart 1: 核心函数覆盖率 ──
  function renderFuncBars(funcs) {
    var chart = echarts.init(document.getElementById('chart-func-bars'), null, { renderer: 'svg' });
    var names = funcs.map(function(f) { return f.function; });
    var pcts = funcs.map(function(f) { return f.pct; });
    var ends = funcs.map(function(f) { return f.end_line - f.start_line + 1; });

    chart.setOption({
      animation: false,
      tooltip: {
        trigger: 'axis',
        appendToBody: true,
        backgroundColor: bg2,
        borderColor: rule,
        textStyle: { color: ink, fontSize: 13 },
        formatter: function(p) {
          var idx = p[0].dataIndex;
          var f = funcs[idx];
          return '<strong>' + f.function + '</strong><br/>' +
                 '覆盖率：<span style="color:' + accent + '">' + f.pct + '%</span><br/>' +
                 '执行 ' + f.executed + ' / ' + f.total_lines + ' 行<br/>' +
                 '位置：' + f.file + ' L' + f.start_line + '–L' + f.end_line + '<br/>' +
                 (f.pct < 95
                   ? '<span style="color:' + warn + '">⚠ 未覆盖 ' + (f.total_lines - f.executed) + ' 行</span>'
                   : '<span style="color:' + ok + '">✓ 覆盖良好</span>');
        }
      },
      grid: { left: 160, right: 40, top: 40, bottom: 30 },
      xAxis: {
        type: 'value',
        max: 100,
        axisLine: { lineStyle: { color: rule } },
        axisLabel: { color: muted, formatter: '{value}%' },
        splitLine: { lineStyle: { color: rule, type: 'dashed' } }
      },
      yAxis: {
        type: 'category',
        data: names,
        axisLine: { lineStyle: { color: rule } },
        axisLabel: { color: ink, fontFamily: 'JetBrainsMono', fontSize: 13 },
        axisTick: { show: false }
      },
      series: [{
        type: 'bar',
        data: pcts.map(function(v, i) {
          var color = v >= 95 ? ok : (v >= 80 ? accent : (v >= 60 ? warn : bad));
          return {
            value: v,
            itemStyle: {
              color: color,
              borderRadius: [0, 4, 4, 0]
            },
            label: {
              show: true, position: 'right',
              color: ink, fontWeight: 600, fontSize: 14,
              formatter: function(p) { return p.value + '%'; }
            }
          };
        }),
        barWidth: 26
      }]
    });
    window.addEventListener('resize', function() { chart.resize(); });
  }

  // ── Chart 2: 未覆盖行分类 ──
  function renderCategoryPie(cats) {
    var chart = echarts.init(document.getElementById('chart-category-pie'), null, { renderer: 'svg' });
    var palette = [accent, accent2, warn, bad, muted, ok];
    var items = Object.keys(cats).map(function(k) { return { name: k, value: cats[k] }; });
    // 按数量排序
    items.sort(function(a, b) { return b.value - a.value; });

    chart.setOption({
      animation: false,
      tooltip: {
        trigger: 'item',
        appendToBody: true,
        backgroundColor: bg2,
        borderColor: rule,
        textStyle: { color: ink, fontSize: 13 },
        formatter: '{b}<br/>{c} 行 ({d}%)'
      },
      legend: {
        orient: 'vertical',
        right: 20,
        top: 'middle',
        textStyle: { color: ink, fontSize: 13 },
        itemGap: 14
      },
      color: palette,
      series: [{
        name: '未覆盖行',
        type: 'pie',
        radius: ['45%', '72%'],
        center: ['40%', '50%'],
        avoidLabelOverlap: true,
        itemStyle: {
          borderColor: bg2,
          borderWidth: 2,
          borderRadius: 4
        },
        label: {
          show: true,
          color: ink,
          fontSize: 13,
          formatter: '{b}\n{d}%'
        },
        labelLine: { lineStyle: { color: rule } },
        data: items
      }]
    });
    window.addEventListener('resize', function() { chart.resize(); });
  }

  // ── Chart 3: 关键文件执行 vs 未执行 ──
  function renderFileStack(files) {
    var chart = echarts.init(document.getElementById('chart-file-stack'), null, { renderer: 'svg' });
    var names = files.map(function(f) { return f.name; });
    var execData = files.map(function(f) { return f.executed; });
    var missData = files.map(function(f) { return f.statements - f.executed; });
    var pcts = files.map(function(f) { return f.pct; });

    chart.setOption({
      animation: false,
      tooltip: {
        trigger: 'axis',
        appendToBody: true,
        backgroundColor: bg2,
        borderColor: rule,
        textStyle: { color: ink, fontSize: 13 },
        axisPointer: { type: 'shadow' },
        formatter: function(ps) {
          var idx = ps[0].dataIndex;
          var f = files[idx];
          return '<strong>' + f.name + '</strong><br/>' +
                 '总语句：' + f.statements + '<br/>' +
                 '<span style="color:' + ok + '">✓ 已执行：' + f.executed + '</span><br/>' +
                 '<span style="color:' + bad + '">✗ 未覆盖：' + (f.statements - f.executed) + '</span><br/>' +
                 '覆盖率：<strong>' + f.pct + '%</strong>';
        }
      },
      legend: {
        data: ['已执行', '未覆盖'],
        textStyle: { color: ink, fontSize: 13 },
        top: 0, right: 20
      },
      grid: { left: 30, right: 30, top: 40, bottom: 50 },
      xAxis: {
        type: 'category',
        data: names,
        axisLine: { lineStyle: { color: rule } },
        axisLabel: {
          color: muted, fontSize: 11,
          interval: 0,
          rotate: 15
        },
        axisTick: { show: false }
      },
      yAxis: {
        type: 'value',
        axisLine: { lineStyle: { color: rule } },
        axisLabel: { color: muted },
        splitLine: { lineStyle: { color: rule, type: 'dashed' } }
      },
      series: [
        {
          name: '已执行',
          type: 'bar',
          stack: 'total',
          data: execData,
          itemStyle: { color: ok, borderRadius: [0, 0, 0, 0] },
          barWidth: 32,
          label: {
            show: true, position: 'inside',
            color: '#fff', fontWeight: 600, fontSize: 12,
            formatter: function(p) { return p.value || ''; }
          }
        },
        {
          name: '未覆盖',
          type: 'bar',
          stack: 'total',
          data: missData,
          itemStyle: { color: bad, borderRadius: [4, 4, 0, 0] },
          label: {
            show: true, position: 'top',
            color: ink, fontWeight: 600, fontSize: 12,
            formatter: function(ps) {
              var idx = ps.dataIndex;
              return pcts[idx] + '%';
            }
          }
        }
      ]
    });
    window.addEventListener('resize', function() { chart.resize(); });
  }
})();
